package cache

import (
	"errors"
	"sync/atomic"
	"time"

	"github.com/jellydator/ttlcache/v3"
)

type SimpleCache[K comparable, V any] interface {
	Add(key K, value V) error
	AddWithTTL(key K, value V, ttl time.Duration) error
	Get(key K) (V, error)
	GetWithLoader(key K, loader func(key K) (V, time.Duration, error)) (V, error)
	Keys() []K
	Values() []V
}

type Options struct {
	SizeLimit  uint64
	DefaultTTL time.Duration
}

func NewSimpleCache[K comparable, V any](options ...Options) SimpleCache[K, V] {
	opts := []ttlcache.Option[K, V]{
		ttlcache.WithDisableTouchOnHit[K, V](),
	}
	if len(options) > 0 {
		o := options[0]
		if o.SizeLimit > 0 {
			opts = append(opts, ttlcache.WithCapacity[K, V](o.SizeLimit))
		}
		if o.DefaultTTL > 0 {
			opts = append(opts, ttlcache.WithTTL[K, V](o.DefaultTTL))
		}
	}

	c := ttlcache.New[K, V](opts...)
	return &simpleCache[K, V]{
		data: c,
	}
}

type simpleCache[K comparable, V any] struct {
	data             *ttlcache.Cache[K, V]
	evictionDeadline atomic.Pointer[time.Time]
}

// scheduleEviction keeps the earliest known expiration as the next sweep time.
func (c *simpleCache[K, V]) scheduleEviction(expiresAt time.Time) {
	if expiresAt.IsZero() {
		return
	}
	for {
		deadline := c.evictionDeadline.Load()
		if deadline != nil && !expiresAt.Before(*deadline) {
			return
		}
		if c.evictionDeadline.CompareAndSwap(deadline, &expiresAt) {
			return
		}
	}
}

func (c *simpleCache[K, V]) evictExpired() {
	deadline := c.evictionDeadline.Load()
	if deadline == nil || time.Now().Before(*deadline) {
		return
	}
	if !c.evictionDeadline.CompareAndSwap(deadline, nil) {
		return
	}

	c.data.DeleteExpired()
	for _, key := range c.data.Keys() {
		if item := c.data.Get(key); item != nil {
			c.scheduleEviction(item.ExpiresAt())
		}
	}
}

func (c *simpleCache[K, V]) Add(key K, value V) error {
	return c.AddWithTTL(key, value, ttlcache.DefaultTTL)
}

func (c *simpleCache[K, V]) AddWithTTL(key K, value V, ttl time.Duration) error {
	c.evictExpired()
	item := c.data.Set(key, value, ttl)
	if item == nil {
		return errors.New("failed to add item")
	}
	c.scheduleEviction(item.ExpiresAt())
	return nil
}

func (c *simpleCache[K, V]) Get(key K) (V, error) {
	c.evictExpired()
	item := c.data.Get(key)
	if item == nil {
		var zero V
		return zero, errors.New("item not found")
	}
	return item.Value(), nil
}

func (c *simpleCache[K, V]) GetWithLoader(key K, loader func(key K) (V, time.Duration, error)) (V, error) {
	c.evictExpired()
	loaderWrapper := ttlcache.LoaderFunc[K, V](
		func(t *ttlcache.Cache[K, V], key K) *ttlcache.Item[K, V] {
			value, ttl, err := loader(key)
			if err != nil {
				return nil
			}
			c.evictExpired()
			item := t.Set(key, value, ttl)
			if item != nil {
				c.scheduleEviction(item.ExpiresAt())
			}
			return item
		},
	)
	item := c.data.Get(key, ttlcache.WithLoader[K, V](loaderWrapper))
	if item == nil {
		var zero V
		return zero, errors.New("item not found")
	}
	return item.Value(), nil
}

func (c *simpleCache[K, V]) Keys() []K {
	c.evictExpired()
	allKeys := c.data.Keys()
	keys := make([]K, 0, len(allKeys))
	for _, key := range allKeys {
		if c.data.Get(key) != nil {
			keys = append(keys, key)
		}
	}
	return keys
}

func (c *simpleCache[K, V]) Values() []V {
	c.evictExpired()
	allKeys := c.data.Keys()
	values := make([]V, 0, len(allKeys))
	for _, key := range allKeys {
		if item := c.data.Get(key); item != nil {
			values = append(values, item.Value())
		}
	}
	return values
}

package cache

import (
	"errors"
	"fmt"
	"time"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("SimpleCache", func() {
	var (
		cache SimpleCache[string, string]
	)

	BeforeEach(func() {
		cache = NewSimpleCache[string, string]()
	})

	Describe("Add and Get", func() {
		It("should add and retrieve a value", func() {
			err := cache.Add("key", "value")
			Expect(err).NotTo(HaveOccurred())

			value, err := cache.Get("key")
			Expect(err).NotTo(HaveOccurred())
			Expect(value).To(Equal("value"))
		})
	})

	Describe("AddWithTTL and Get", func() {
		It("should add a value with TTL and retrieve it", func() {
			err := cache.AddWithTTL("key", "value", 1*time.Second)
			Expect(err).NotTo(HaveOccurred())

			value, err := cache.Get("key")
			Expect(err).NotTo(HaveOccurred())
			Expect(value).To(Equal("value"))
		})

		It("should not retrieve a value after its TTL has expired", func() {
			err := cache.AddWithTTL("key", "value", 10*time.Millisecond)
			Expect(err).NotTo(HaveOccurred())

			time.Sleep(50 * time.Millisecond)

			_, err = cache.Get("key")
			Expect(err).To(HaveOccurred())
		})
	})

	Describe("GetWithLoader", func() {
		It("should retrieve a value using the loader function", func() {
			loader := func(key string) (string, time.Duration, error) {
				return "value", 1 * time.Second, nil
			}

			value, err := cache.GetWithLoader("key", loader)
			Expect(err).NotTo(HaveOccurred())
			Expect(value).To(Equal("value"))
		})

		It("should return the error returned by the loader function", func() {
			loader := func(key string) (string, time.Duration, error) {
				return "", 0, errors.New("some error")
			}

			_, err := cache.GetWithLoader("key", loader)
			Expect(err).To(HaveOccurred())
		})

		It("should replace an expired value with the loader's value and TTL", func() {
			_ = cache.AddWithTTL("key", "old", 10*time.Millisecond)
			time.Sleep(50 * time.Millisecond)

			value, err := cache.GetWithLoader("key", func(key string) (string, time.Duration, error) {
				return key + "=value", 10 * time.Millisecond, nil
			})
			Expect(err).NotTo(HaveOccurred())
			Expect(value).To(Equal("key=value"))
			Expect(cache.Values()).To(ConsistOf("key=value"))

			time.Sleep(50 * time.Millisecond)
			Expect(cache.Keys()).To(BeEmpty())
			Expect(cache.Values()).To(BeEmpty())
			Expect(cache.(*simpleCache[string, string]).data.Len()).To(Equal(0))
		})
	})

	Describe("Keys", func() {
		It("should return all keys", func() {
			err := cache.Add("key1", "value1")
			Expect(err).NotTo(HaveOccurred())

			err = cache.Add("key2", "value2")
			Expect(err).NotTo(HaveOccurred())

			keys := cache.Keys()
			Expect(keys).To(ConsistOf("key1", "key2"))
		})

		It("should omit expired entries from keys and values", func() {
			_ = cache.Add("active", "active=value")
			_ = cache.AddWithTTL("expired", "expired=value", 10*time.Millisecond)
			time.Sleep(50 * time.Millisecond)

			Expect(cache.Keys()).To(ConsistOf("active"))
			Expect(cache.Values()).To(ConsistOf("active=value"))
			Expect(cache.(*simpleCache[string, string]).data.Len()).To(Equal(1))
		})
	})

	Describe("Options", func() {
		Context("when size limit is set", func() {
			BeforeEach(func() {
				cache = NewSimpleCache[string, string](Options{
					SizeLimit: 2,
				})
			})

			It("should not add more items than the size limit", func() {
				for i := 1; i <= 3; i++ {
					err := cache.Add(fmt.Sprintf("key%d", i), fmt.Sprintf("value%d", i))
					Expect(err).NotTo(HaveOccurred())
				}

				Expect(cache.Keys()).To(ConsistOf("key2", "key3"))
			})

			It("should evict expired entries before applying the size limit", func() {
				_ = cache.Add("active", "active=value")
				_ = cache.AddWithTTL("expired", "expired=value", 10*time.Millisecond)
				time.Sleep(50 * time.Millisecond)

				Expect(cache.Add("new", "new=value")).To(Succeed())
				Expect(cache.Keys()).To(ConsistOf("active", "new"))
				Expect(cache.Values()).To(ConsistOf("active=value", "new=value"))
			})
		})

		Context("when default TTL is set", func() {
			BeforeEach(func() {
				cache = NewSimpleCache[string, string](Options{
					DefaultTTL: 10 * time.Millisecond,
				})
			})

			It("should expire items after the default TTL", func() {
				_ = cache.Add("key", "value")

				time.Sleep(50 * time.Millisecond)

				_, err := cache.Get("key")
				Expect(err).To(HaveOccurred())
			})
		})
	})
})

